<?php
namespace Modules\ExpensesNew\Http\Controllers;
use Illuminate\Routing\Controller; use Illuminate\Http\Request; use Modules\ExpensesNew\Entities\Payee; use Modules\ExpensesNew\Services\PayeeSyncService; use Modules\ExpensesNew\Utils\BusinessScope;
class PayeeController extends Controller{ public function index(){return view('expensesnew::payees.index');} public function create(){return view('expensesnew::payees.form',['payee'=>new Payee()]);} public function store(Request $r){$r->validate(['name'=>'required|max:191']);Payee::create($r->only(['name','mobile','email','address'])+['business_id'=>BusinessScope::businessId(),'is_active'=>1,'created_by'=>auth()->id()]);return redirect()->route('expensesnew.payees.index')->with('status','Payee saved');} public function edit($id){$payee=Payee::where('business_id',BusinessScope::businessId())->findOrFail($id);return view('expensesnew::payees.form',compact('payee'));} public function update(Request $r,$id){$payee=Payee::where('business_id',BusinessScope::businessId())->findOrFail($id);$payee->update($r->only(['name','mobile','email','address'])+['is_active'=>$r->has('is_active')?1:0]);return redirect()->route('expensesnew.payees.index')->with('status','Payee updated');} public function destroy($id){Payee::where('business_id',BusinessScope::businessId())->findOrFail($id)->delete();return response()->json(['success'=>true]);} public function syncChequePayees(PayeeSyncService $service){$count=$service->syncFromChequePayees(BusinessScope::businessId());return back()->with('status',$count.' payee(s) synced into Expenses-New');} public function data(){ $rows=Payee::where('business_id',BusinessScope::businessId())->orderBy('name')->get(); return response()->json(['data'=>$rows->map(fn($p)=>['id'=>$p->id,'name'=>$p->name,'mobile'=>$p->mobile,'email'=>$p->email,'active'=>$p->is_active?'Yes':'No','action'=>view('expensesnew::payees.partials.actions',compact('p'))->render()])]);}}
